import { r as registerInstance, c as createEvent, a as getElement, h } from './index-DlAp0uRx.js';

const dropdownMenuCss = () => `:host{position:relative;z-index:1000}.dropdown-menu{display:none;visibility:hidden;flex-direction:column;width:224px;max-height:289px;min-width:224px;overflow-y:auto;background:#ffffff;box-shadow:0 4px 16px 0 rgba(29, 29, 29, 0.12);border:1px solid #eeeded;padding:8px 0;font-family:var(--ifx-font-family)}.dropdown-menu.small{max-height:266px;max-width:186px;overflow-y:auto}.dropdown-menu.has-top-content{padding-top:0}.dropdown-menu ::slotted(ifx-search-field){padding:16px}.dropdown-menu ::slotted(ifx-dropdown-header){margin-bottom:8px}.dropdown-menu.show{display:flex;visibility:visible}`;

const DropdownMenu = class {
    constructor(hostRef) {
        registerInstance(this, hostRef);
        this.menuSize = createEvent(this, "menuSize", 7);
        this.ifxDropdownMenuItem = createEvent(this, "ifxDropdownMenuItem", 7);
    }
    /** Controls wether the dropdown menu is open or closed. */
    isOpen = false;
    /**
     * Size of the dropdown menu.
     * @default "l"
     */
    size = "l";
    hasTopContent = false;
    get el() { return getElement(this); }
    /** Emits the calculated size of the menu */
    menuSize;
    filteredItems = [];
    /** Fired when a dropdown menu item is selected */
    ifxDropdownMenuItem;
    handleMenuFilter(event) {
        const searchValue = event.detail;
        this.filterDropdownItems(searchValue);
    }
    handleDropdownItemValueEmission(event) {
        this.ifxDropdownMenuItem.emit(event.detail);
    }
    filterDropdownItems(searchValue) {
        const allItems = Array.from(this.el.querySelectorAll("ifx-dropdown-item"));
        const query = searchValue.toUpperCase();
        for (const dropdownItem of allItems) {
            const txtValue = dropdownItem.textContent || dropdownItem.innerText;
            dropdownItem.hide = !txtValue.toUpperCase().includes(query);
        }
    }
    componentWillUpdate() {
        this.menuSize.emit(this.size);
    }
    componentWillLoad() {
        this.filteredItems = Array.from(this.el.querySelectorAll("ifx-dropdown-item"));
        this.hasTopContent = Boolean(this.el.querySelector("ifx-search-field, ifx-dropdown-header"));
    }
    render() {
        return (h("div", { key: 'ae4eaa861ba358b9f47d6bea6cab13d9fb39b91c', class: `dropdown-menu 
      ${this.isOpen ? "show" : ""} 
	  ${this.hasTopContent ? "has-top-content" : ""}
      ${this.size === "s" ? "small" : ""}` }, h("slot", { key: '41f5ed7081230eee73ea7d9cef18ba11409abf8b' })));
    }
};
DropdownMenu.style = dropdownMenuCss();

export { DropdownMenu as ifx_dropdown_menu };
